import { get_location_details } from "@/mixins/GetLocations.js";
import { map_rfid_location } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  mixins: [get_location_details],
  props: {
    rfidCreation: Boolean
  },
  data() {
    return {
      loading: false,
      rfidId: "",
      loaction: "",
      searchloc: "",
      loactionitems: []
    };
  },
  watch: {
    rfidCreation: {
      async handler() {
        await this.get_location_details();
        await this.fetch_details();
      },
      immediate: true
    }
  },
  methods: {
    fetch_details() {
      this.locationList.forEach(element => {
        if (element.location_name != "Scan AnyWhere") this.loactionitems.push({
          title: element.location_name,
          value: element.location_id
        });
      });
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    async delete_mutation() {
      const {
        valid
      } = await this.$refs.form?.validate?.();
      if (valid) {
        this.loading = true;
        var data = this.$store.getters.GetUserObj;
        try {
          let result = await API.graphql(graphqlOperation(map_rfid_location, {
            input: {
              rfid_box_id: this.rfidId,
              location_id: this.loaction
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.map_rfid_location);
          this.loading = false;
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
            this.$refs.form.resetValidation();
            this.$refs.form.reset();
          } else {
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          this.loading = false;
          this.$emit("errorMsg", error.errors[0].message);
        }
      }
    }
  }
};
